# List List Компонент списка Компонент представляет собой список состоящий из  `ListItem` . ListItem представляет собой простой компонент с текстом и иконкой ### Типы ListItem Типы ListItem ## Примеры Примеры ### Базовое использование Базовое использование ```tsx
import React from 'react';
import { List, ListItem } from '@salutejs/sdds-finai';
import { IconChevronRight } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <List view="default" size="s" variant="normal">
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 1</ListItem>
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 2</ListItem>
                <ListItem disabled contentRight={<IconChevronRight color="inherit" size="xs" />}>
                    Test Item 3
                </ListItem>
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 4</ListItem>
            </List>
        </div>
    );
}
```

### Разделители между элементами Разделители между элементами Свойство  `hasDivider`  добавляет разделители между элементами списка. ```tsx
import React from 'react';
import { List, ListItem } from '@salutejs/sdds-finai';
import { IconChevronRight } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <List view="default" size="s" variant="normal" hasDivider>
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 1</ListItem>
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 2</ListItem>
                <ListItem disabled contentRight={<IconChevronRight color="inherit" size="xs" />}>
                    Test Item 3
                </ListItem>
                <ListItem contentRight={<IconChevronRight color="inherit" size="xs" />}>Test Item 4</ListItem>
            </List>
        </div>
    );
}
```
